void introDrawLogo(Adafruit_GC9A01A &tft) {
    const int16_t x = (TFT_WIDTH  - INTRO_LOGO_WIDTH)  / 2;
    const int16_t y = (TFT_HEIGHT - INTRO_LOGO_HEIGHT) / 2 + INTRO_LOGO_Y_OFFSET;
    tft.fillScreen(GC9A01A_BLACK);
    tft.drawBitmap(x, y, INTRO_LOGO_BMP,
                   INTRO_LOGO_WIDTH, INTRO_LOGO_HEIGHT, GC9A01A_CYAN);
}

void introShow(Adafruit_GC9A01A &tft, uint16_t durationMs) {
    introDrawLogo(tft);
    delay(durationMs);
    tft.fillScreen(GC9A01A_BLACK);
}
